-- 3. Product 1: Artisanal Roasted Peri Peri Jumbo Makhana INSERT INTO catalog_products (id, slug, name, brand, short_description, description, category_id, hsn_code, tax_rate_percent, attributes, is_published) VALUES ( 'f0000000-0000-0000-0000-000000000001', 'artisanal-roasted-peri-peri-jumbo-makhana', 'Artisanal Roasted Peri Peri Jumbo Makhana', 'Mito Crunch', 'Crispy slow-roasted foxnuts dusted with zesty African bird''s eye chili peri peri spice.', 'Crafted from hand-graded jumbo foxnuts cultivated in the pristine freshwater ponds of Mithila. Slowly slow-roasted to golden crispness in cold-pressed rice bran oil and coated with our secret peri-peri seasoning.', 'e0000000-0000-0000-0000-000000000001', '19041090', 5.00, '{"dietary": ["Gluten-Free", "Vegan", "High-Protein"], "process": "Slow Roasted", "roastingProcess": "Hot Air Roasted", "shelfLifeDays": 180}'::jsonb, true ) ON CONFLICT (slug) DO NOTHING;
