-- 4. Product 2: Himalayan Pink Salt Organic Foxnuts INSERT INTO catalog_products (id, slug, name, brand, short_description, description, category_id, hsn_code, tax_rate_percent, attributes, is_published) VALUES ( 'f0000000-0000-0000-0000-000000000002', 'himalayan-pink-salt-organic-foxnuts', 'Himalayan Pink Salt Organic Foxnuts', 'Mito Crunch', 'Subtly seasoned with mineral-rich Himalayan pink salt for an authentic crunch.', 'Pure simplicity at its best. Naturally puffed organic foxnuts lightly tossed in stone-ground Himalayan pink rock salt and extra virgin olive oil.', 'e0000000-0000-0000-0000-000000000001', '19041090', 5.00, '{"dietary": ["Gluten-Free", "Keto-Friendly", "Low-Sodium"], "process": "Light Roasted", "roastingProcess": "Hot Air Roasted", "shelfLifeDays": 180}'::jsonb, true ) ON CONFLICT (slug) DO NOTHING;
